OWN)] = if (rl.isKeyDown(rl.KeyboardKey.key_down)) 1 else 0;         controllerState[@intFromEnum(ControllerEvents.LEFT)] = if (rl.isKeyDown(rl.KeyboardKey.key_left)) 1 else 0;         controllerState[@intFromEnum(ControllerEvents.RIGHT)] = if (rl.isKeyDown(rl.KeyboardKey.key_right)) 1 else 0;          // Send the current state of the controller to the server         const addr = try net.Address.parseIp4("127.0.0.1", 31415);         try sendControllerState(sock, &addr, &controllerState);           // Draw         //----------------------------------------------------------------------------------         rl.beginDrawing();         rl.clearBackground(rl.Color.white);         rl.drawText("Press arrow keys to simulate controller input!", 190, 200, 20, rl.Color.light_gray);         rl.endDrawing();         //----------------------------------------------------------------------------------     } } ``` Here is example Zig array that contains valid data: ``` // Simulated values for each event var eventCodesValues = [_][2]i16{     .{0, 32767},  // ANALOG_LX (full right)     .{1, 0},      // ANALOG_LY (center)     .{2, -32768}, // ANALOG_RX (full left)     .{3, 0},      // ANALOG_RY (center)     .{4, 1},      // L1 (pressed)     .{5, 0},      // L2 (released)     .{6, 1},      // R1 (pressed)     .{7, 0},      // R2 (released)     .{8, 1},      // TRIANGLE (pressed)     .{9, 0},      // CROSS (released)     .{10, 1},     // SQUARE (pressed)     .{11, 0},     // CIRCLE (released)     .{12, 1},     // UP (pressed)     .{13, 0},     // DOWN (released)     .{14, 1},     // LEFT (pressed)     .{15, 0},     // RIGHT (released)     .{16, 1},     // SELECT (pressed)     .{17, 0}      // START (released) }; ``` Modify client and server to use the same binary data format.

